with UserBadgeStats as (
    select 
        u.Id as UserId,
        u.DisplayName,
        u.Reputation,
        u.CreationDate,
        count(b.Id) as TotalBadges,
        count(distinct case when b.Class = 1 then b.Id end) as GoldBadges,
        count(distinct case when b.Class = 2 then b.Id end) as SilverBadges,
        count(distinct case when b.Class = 3 then b.Id end) as BronzeBadges,
        count(distinct case when b.TagBased = cast(1 as bit) then b.Id end) as TagBasedBadges,
        
        rank() over (partition by None order by u.Reputation desc) as ReputationRank
    from 
        Users u
        left join Badges b on b.UserId = u.Id
    group by 
        u.Id,
        u.DisplayName,
        u.Reputation,
        u.CreationDate
), RecentPopularAnsweredQuestionStats as (
    select
        p.Id as QuestionID,
        p.Title,
        p.CreationDate,
        p.Tags,
